import{_ as a,H as n,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"27 | 命令行：不只是酷，更重要的是能提高个人效能","description":"","frontmatter":{},"headers":[{"level":2,"title":"为什么要使用命令行？","slug":"为什么要使用命令行","link":"#为什么要使用命令行","children":[]},{"level":2,"title":"第一步，选择模拟终端","slug":"第一步-选择模拟终端","link":"#第一步-选择模拟终端","children":[]},{"level":2,"title":"第二步，选择Shell","slug":"第二步-选择shell","link":"#第二步-选择shell","children":[]},{"level":2,"title":"第三步，具体的Shell配置","slug":"第三步-具体的shell配置","link":"#第三步-具体的shell配置","children":[]},{"level":2,"title":"第四步，远程SSH的处理","slug":"第四步-远程ssh的处理","link":"#第四步-远程ssh的处理","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"研发效率破局之道/27-命令行：不只是酷，更重要的是能提高个人效能.md","filePath":"研发效率破局之道/27-命令行：不只是酷，更重要的是能提高个人效能.md","lastUpdated":1779821359000}'),t={name:"研发效率破局之道/27-命令行：不只是酷，更重要的是能提高个人效能.md"};function i(l,s,o,r,h,c){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="_27-命令行-不只是酷-更重要的是能提高个人效能" tabindex="-1">27 | 命令行：不只是酷，更重要的是能提高个人效能 <a class="header-anchor" href="#_27-命令行-不只是酷-更重要的是能提高个人效能" aria-label="Permalink to &quot;27 | 命令行：不只是酷，更重要的是能提高个人效能&quot;">​</a></h1><p>你好，我是葛俊。今天，我要与你分享的主题是，命令行下的高效工作技巧。</p><p>我先和你讲一个有意思的话题吧。命令行工具常常会给人一种黑客的感觉，好莱坞的电影里面常常出现命令行窗口的使用。不知道你听说过没有，很多好莱坞电影在拍摄时使用的其实是一个叫作 <a href="https://nmap.org" target="_blank" rel="noreferrer">nmap</a> 的工具。这个工具是做安全扫描的，只不过因为它的显示特别花哨，所以被很多电影采用。在nmap官方网站上，还专门列出来了这些电影的名单。</p><p>类似这种可以让自己看起来很忙的工具还有很多，比如 <a href="https://github.com/svenstaro/genact" target="_blank" rel="noreferrer">Genact</a>。下面是一个使用Genact的录屏，当然这里的命令并没有真正运行。这可能是整个专栏中，唯一一个让你看起来效率很高，实际上却是降低效率的工具，但说不定对你有用，你懂的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/2dba0dfdd5f0260ad3b3082a7d3d2697.gif" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/2dba0dfdd5f0260ad3b3082a7d3d2697.gif" alt=""></a></p><p>讲完这个娱乐性的话题，我们进入正题吧。</p><h2 id="为什么要使用命令行" tabindex="-1">为什么要使用命令行？ <a class="header-anchor" href="#为什么要使用命令行" aria-label="Permalink to &quot;为什么要使用命令行？&quot;">​</a></h2><p>GUI图形界面的出现是计算机技术的变革，极大方便了用户。但在这么多年后的今天，命令行工具为什么仍然有如此强大的生命力呢？</p><p>在我看来，对软件工程师来说，想要高效开发就必须掌握命令行，主要原因包括：</p><ul><li>虽然鼠标的移动和点击比较直观，但要完成重复性的工作，使用键盘会快捷得多。这一点从超市的结算人员就可以看出来，使用键盘系统的收银员总是噼里啪啦地很快就可以完成结算，而使用鼠标点击的话明显慢很多。</li><li>作为开发人员，可以比较容易地使用命令行的脚本，对自己的工作进行自动化，以及和其他系统工具联动。但使用GUI的话，就会困难得多。</li><li>命令行通常可以暴露更完整的功能，让使用者对整个系统有更透彻的理解。Git就是一个典型的例子，再好的GUI Git系统都只能封装一部分Git命令行功能，要想真正了解Git，我们必须要使用命令行。</li><li>有一些情况是必须使用命令行的，比如SSH到远程服务器上工作的时候。</li></ul><p>为了演示命令行的强大功能给我们带来的方便，下面是一个在本地查看文件并上传到服务器的流程的录屏。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/1deb0006ea65cd5c4a28819a2cf50629.gif" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/1deb0006ea65cd5c4a28819a2cf50629.gif" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/958987c6594699ff1fb97b1622b21a40.gif" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/958987c6594699ff1fb97b1622b21a40.gif" alt=""></a></p><p>通过这个案例，你可以看到命令行的以下几个功能：</p><ul><li>在提示行会高亮显示时间、机器名、用户名、Git代码仓的分支和状态，以及上一个命令的完成状态。</li><li>输入命令的时候，高亮显示错误并自动纠错。</li><li>使用交互的形式进行文件夹的跳转，并方便查找文件，还可以直接在命令行里显示图片。</li><li>使用交互的工具，把文件上传到远端的服务器，并快速连接到远端查看传输是否成功。</li></ul><p>整个流程全部都是在命令行里完成的，速度非常快，用户体验也非常好。正因为如此，我看到的硅谷特别高效的开发人员，绝大多数都大量使用命令行。那，面对成百上千的命令行工具，我们 <strong>怎样才能高效地学习和使用</strong> 呢？</p><p>我将高效学习使用命令行的过程，归纳为两大步：</p><ol><li>配置好环境；</li><li>针对自己最常使用命令行的场景，有的放矢地选择工具。</li></ol><p>今天，我就与你详细讲述 <strong>环境配置</strong> 这个话题。而关于选择工具的话题，我会在下一篇文章中与你详细介绍。总结来讲，环境配置主要包括以下四步：</p><ol><li>选择模拟终端；</li><li>选择Shell；</li><li>具体的Shell配置；</li><li>远程SSH的处理。</li></ol><p>这里需要注意的是，在命令行方面，macOS和Linux系统比Windows系统要强大许多，所以我主要以macOS和Linux系统来介绍，而关于Windows的环境配置，我只会捎带提一下。不过，macOS和Linux系统中的工具选择和配置思路，你可以借鉴到Windows系统中。</p><h2 id="第一步-选择模拟终端" tabindex="-1">第一步，选择模拟终端 <a class="header-anchor" href="#第一步-选择模拟终端" aria-label="Permalink to &quot;第一步，选择模拟终端&quot;">​</a></h2><p>我将一个好的终端应该具有的特征，归纳为4个：</p><ul><li>快，稳定；</li><li>支持多终端，比如可以方便地水平和纵向分屏，有tab等；</li><li>方便配置字体颜色等；</li><li>方便管理常用SSH的登录。</li></ul><p>macOS系统自带的终端不太好用，常见的替代工具有iTerm2、Terminator、Hyper和Upterm。我平时使用的iTerm2，是一个免费软件，功能强大，具备上面提到的4个特征。下面我就以iTerm2为例展开介绍。其他几个工具上也有类似功能，所以你不必担心。</p><p>在多终端的场景方面，iTerm2支持多窗口、多标签页，同一窗口中可以进行多次水平和纵向分屏。这些操作以及窗口的跳转都有快捷键支持，你可以很方便地在网络上搜索到。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/d63c4054e8e23136da22b1d9d6e4c2bf.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/d63c4054e8e23136da22b1d9d6e4c2bf.png" alt=""></a></p><p>在管理常用SSH的登录方面，iTerm2使用Profile（用户画像）来控制。比如，下面是一个连接到远程服务器案例的录屏。</p><p>可以看到，在我的工作环境里常会用到4个Profile，其中有两个是连接到远端服务器的，包括Mosh Remote Server 1和SSH Remote Server 2。工作时，我使用Cmd+O，然后选择Server 1这个Profile，就可以打开一个新窗口，连接到这个远程服务器上。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/ec60c3bf9bb2688ea59e76b1576078ae.gif" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/ec60c3bf9bb2688ea59e76b1576078ae.gif" alt=""></a></p><p>每一个Profile都可以定义自己的字体、颜色、shell命令等。比如，Server 1是类生产服务器，我就把背景设置成了棕红色，提醒自己在这个机器上工作时一定要小心。所以在上面的录屏中你可以看到，连接到远端的SSH标签页，它的背景、标签页都是棕红色。另外，下面是如何对Profile颜色进行设置的截屏。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/54888d3d58612f9b557af6e45f40b758.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/54888d3d58612f9b557af6e45f40b758.png" alt=""></a></p><p>除了这些基础功能外，iTerm2还有很多贴心的设计。比如：</p><ul><li><strong>在屏幕中显示运行历史</strong>（Cmd+Opt+B/F）。有些情况下，向上滚动终端并不能看到之前的历史，比如运行VIM或者Tmux的时候。这时，浏览显示历史就特别有用了。</li><li><strong>高亮显示当前编辑位置</strong>，包括高亮显示当前行（Cmd+Opt+；）高亮显示光标所在位置（Cmd+/）。</li><li><strong>与上一次运行命令相关的操作</strong>，包括显示上一次运行命令的地方（Cmd+Shift+up），选中上一个命令的输出（Cmd+Shift+A）。</li></ul><p>其中第2、3项功能是由一组 <a href="https://www.iterm2.com/documentation-utilities.html" target="_blank" rel="noreferrer">macOS的集成工具</a> 提供的。这个工具集还包括显示图片的命令imgls、imgcat，显示自动补全命令，显示时间、注释，以及在主窗口旁显示额外信息等。这些设计虽然很小，但非常实用。</p><p>关于Windows系统，2019年5月微软推出了 <a href="https://devblogs.microsoft.com/commandline/introducing-windows-terminal/" target="_blank" rel="noreferrer">Windows Terminal</a>，支持多Tab，定制性很强，据说体验很不错。</p><p>选择好了终端，环境设置的第二步就是选择Shell。</p><h2 id="第二步-选择shell" tabindex="-1">第二步，选择Shell <a class="header-anchor" href="#第二步-选择shell" aria-label="Permalink to &quot;第二步，选择Shell&quot;">​</a></h2><p>在我看来，选择Shell主要有普遍性和易用性这两条原则。</p><p>Linux/Unix系统下， <strong>Bash</strong> 最普遍、用户群最广，但是易用性不是很好。常用来替代Bash的工具有 <strong>Zsh</strong> 和 <strong>Fish</strong>，它们的易用性都很好。下面是两张图片，用于展示Zsh和Fish在易用性方面的一些功能。</p><p>Zsh：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/3198a7c972939d35de0c03bd26c4a8a6.gif" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/3198a7c972939d35de0c03bd26c4a8a6.gif" alt=""></a></p><p>Fish：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/082720f4dbe7e335a290938993d84732.gif" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/082720f4dbe7e335a290938993d84732.gif" alt=""></a></p><p>我个人觉得Fish比Zsh更方便。事实上，Fish是Friendly Interactive Shell的简称。所以，交互是Fish的强项。可惜的是，Fish不严格遵循POSIX的语法，与Bash的脚本不兼容，而Zsh则兼容，所以我目前主要使用的是Zsh。</p><p>选好了模拟终端和Shell之后，便是配置环境的第三步，具体的Shell配置了。</p><h2 id="第三步-具体的shell配置" tabindex="-1">第三步，具体的Shell配置 <a class="header-anchor" href="#第三步-具体的shell配置" aria-label="Permalink to &quot;第三步，具体的Shell配置&quot;">​</a></h2><p>接下来，我以我自己使用的设置为例，向你介绍Bash、Zsh、Fish的具体配置吧。这里，主要包括 <strong>命令行提示符</strong> 的配置和其他配置两个方面。</p><p>之所以把命令行提示符单独提出来，是因为它一直展现在界面上，能提供很有用的价值，对命令行高效工作至关重要。下面是一张图片，展示了Bash、Zsh和Fish的命令行提示符。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/cd10736ba6a970f9a7f8d2703a4b45bf.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/cd10736ba6a970f9a7f8d2703a4b45bf.png" alt=""></a></p><p>这个窗口分为三部分，最上面是Bash，中间是Zsh，最下面是Fish，都配置了文件路径、Git信息和时间戳等信息。接下来，我带你一起看看这3个工具应该如何配置吧。</p><p><strong>Bash比较麻烦，</strong> 配置文件包括定义颜色和命令行提示符的两部分：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## 文件 $HOME/.bash/term_colors，定义颜色</span></span>
<span class="line"><span># Basic aliases for bash terminal colors</span></span>
<span class="line"><span>N=&quot;\\[\\033[0m\\]&quot;    # unsets color to term&#39;s fg color</span></span>
<span class="line"><span></span></span>
<span class="line"><span># regular colors</span></span>
<span class="line"><span>K=&quot;\\[\\033[0;30m\\]&quot;    # black</span></span>
<span class="line"><span>R=&quot;\\[\\033[0;31m\\]&quot;    # red</span></span>
<span class="line"><span>G=&quot;\\[\\033[0;32m\\]&quot;    # green</span></span>
<span class="line"><span>Y=&quot;\\[\\033[0;33m\\]&quot;    # yellow</span></span>
<span class="line"><span>B=&quot;\\[\\033[0;34m\\]&quot;    # blue</span></span>
<span class="line"><span>M=&quot;\\[\\033[0;35m\\]&quot;    # magenta</span></span>
<span class="line"><span>C=&quot;\\[\\033[0;36m\\]&quot;    # cyan</span></span>
<span class="line"><span>W=&quot;\\[\\033[0;37m\\]&quot;    # white</span></span>
<span class="line"><span></span></span>
<span class="line"><span># empahsized (bolded) colors</span></span>
<span class="line"><span>MK=&quot;\\[\\033[1;30m\\]&quot;</span></span>
<span class="line"><span>MR=&quot;\\[\\033[1;31m\\]&quot;</span></span>
<span class="line"><span>MG=&quot;\\[\\033[1;32m\\]&quot;</span></span>
<span class="line"><span>MY=&quot;\\[\\033[1;33m\\]&quot;</span></span>
<span class="line"><span>MB=&quot;\\[\\033[1;34m\\]&quot;</span></span>
<span class="line"><span>MM=&quot;\\[\\033[1;35m\\]&quot;</span></span>
<span class="line"><span>MC=&quot;\\[\\033[1;36m\\]&quot;</span></span>
<span class="line"><span>MW=&quot;\\[\\033[1;37m\\]&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># background colors</span></span>
<span class="line"><span>BGK=&quot;\\[\\033[40m\\]&quot;</span></span>
<span class="line"><span>BGR=&quot;\\[\\033[41m\\]&quot;</span></span>
<span class="line"><span>BGG=&quot;\\[\\033[42m\\]&quot;</span></span>
<span class="line"><span>BGY=&quot;\\[\\033[43m\\]&quot;</span></span>
<span class="line"><span>BGB=&quot;\\[\\033[44m\\]&quot;</span></span>
<span class="line"><span>BGM=&quot;\\[\\033[45m\\]&quot;</span></span>
<span class="line"><span>BGC=&quot;\\[\\033[46m\\]&quot;</span></span>
<span class="line"><span>BGW=&quot;\\[\\033[47m\\]&quot;</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## 文件 $HOME/.bashrc，设置提示符及其解释</span></span>
<span class="line"><span>###### PROMPT ######</span></span>
<span class="line"><span># Set up the prompt colors</span></span>
<span class="line"><span>source $HOME/.bash/term_colors</span></span>
<span class="line"><span>PROMPT_COLOR=$G</span></span>
<span class="line"><span>if [ \${UID} -eq 0 ]; then</span></span>
<span class="line"><span>  PROMPT_COLOR=$R ### root is a red color prompt</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#t Some good thing about this prompt:</span></span>
<span class="line"><span># (1) The time shows when each command was executed, when I get back to my terminal</span></span>
<span class="line"><span># (2) Git information really important for git users</span></span>
<span class="line"><span># (3) Prompt color is red if I&#39;m root</span></span>
<span class="line"><span># (4) The last part of the prompt can copy/paste directly into an SCP command</span></span>
<span class="line"><span># (5) Color highlight out the current directory because it&#39;s important</span></span>
<span class="line"><span># (6) The export PS1 is simple to understand!</span></span>
<span class="line"><span># (7) If the prev command error codes, the prompt &#39;&amp;gt;&#39; turns red</span></span>
<span class="line"><span>export PS1=&quot;\\e[42m\\t\\e[m$N $W&quot;&#39;$(__git_ps1 &quot;(%s) &quot;)&#39;&quot;$N$PROMPT_COLOR\\u&amp;#64;\\H$N:$C\\w$N\\n\\[&quot;&#39;$CURSOR_COLOR&#39;&quot;\\]&amp;gt;$W &quot;</span></span>
<span class="line"><span>export PROMPT_COMMAND=&#39;if [ $? -ne 0 ]; then CURSOR_COLOR=\`echo -e &quot;\\033[0;31m&quot;\`; else CURSOR_COLOR=&quot;&quot;; fi;&#39;</span></span></code></pre></div><p>命令行提示符之外的其他方面的配置，在Bash方面，我主要设置了一些命令行补全（completion）和别名设置（alias）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## git alias</span></span>
<span class="line"><span>alias g=git</span></span>
<span class="line"><span>alias gro=&#39;git r origin/master&#39;</span></span>
<span class="line"><span>alias grio=&#39;git r -i origin/master&#39;</span></span>
<span class="line"><span>alias gric=&#39;git r --continue&#39;</span></span>
<span class="line"><span>alias gria=&#39;git r --abort&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## ls aliases</span></span>
<span class="line"><span>alias ls=&#39;ls -G&#39;</span></span>
<span class="line"><span>alias la=&#39;ls -la&#39;</span></span>
<span class="line"><span>alias ll=&#39;ls -l&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## git completion，请参考https://github.com/git/git/blob/master/contrib/completion/git-completion.bash</span></span>
<span class="line"><span>source ~/.git-completion.bash</span></span></code></pre></div><p><strong>Zsh的配置就容易得多了，而且是模块化的</strong>。基本上就是安装一个配置的框架，然后选择插件和主题即可。具体来说，我的Zsh命令行提示符配置步骤包括以下三步。</p><p>第一， <a href="https://github.com/robbyrussell/oh-my-zsh" target="_blank" rel="noreferrer">安装oh-my-zsh</a>。这是一个对Zsh进行配置的常用开源框架。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brew install zsh</span></span></code></pre></div><p>第二， <a href="http://powerline" target="_blank" rel="noreferrer">安装powerline字体</a>，供下一步使用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brew install powerlevel9k</span></span></code></pre></div><p>第三，在~/.zshrc中配置ZSH_THEME，指定使用powerlevel9k这个主题。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ZSH_THEME=&quot;powerlevel9k/powerlevel9k&quot;</span></span></code></pre></div><p>命令行提示符以外的其他配置，主要是通过安装和使用oh-my-zsh插件的方式来完成。下面是我使用的各种插件，供你参考。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## 文件~/.zshrc.sh 中关oh-my-zsh的插件列表，具体插件细节请参考https://github.com/robbyrussell/oh-my-zsh，以及使用Web搜索查询</span></span>
<span class="line"><span>plugins=(</span></span>
<span class="line"><span>  git</span></span>
<span class="line"><span>  z</span></span>
<span class="line"><span>  vi-mode</span></span>
<span class="line"><span>  zsh-syntax-highlighting</span></span>
<span class="line"><span>  zsh-autosuggestions</span></span>
<span class="line"><span>  osx</span></span>
<span class="line"><span>  colored-man-pages</span></span>
<span class="line"><span>  catimg</span></span>
<span class="line"><span>  web-search</span></span>
<span class="line"><span>  vscode</span></span>
<span class="line"><span>  docker</span></span>
<span class="line"><span>  docker-compose</span></span>
<span class="line"><span>  copydir</span></span>
<span class="line"><span>  copyfile</span></span>
<span class="line"><span>  npm</span></span>
<span class="line"><span>  yarn</span></span>
<span class="line"><span>  extract</span></span>
<span class="line"><span>  fzf-z</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>source $ZSH/oh-my-zsh.sh</span></span></code></pre></div><p><strong>至于Fish的配置，和Zsh差不多，也是安装一个配置的框架，然后选择插件和主题即可。</strong> 在配置命令行提示符时，主要步骤包括以下两步。</p><p>第一，安装配置管理框架oh-my-fish：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>curl -L https://get.oh-my.fish | fish</span></span></code></pre></div><p>第二，查看、安装、使用oh-my-fish的某个主题，主题会自动配置好命令行提示符：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>omf theme</span></span>
<span class="line"><span>omf install &amp;lt;theme&amp;gt;</span></span>
<span class="line"><span>omf theme &amp;lt;theme&amp;gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 我使用的是bobthefish主题</span></span>
<span class="line"><span>omf theme bobthefish</span></span></code></pre></div><p>这里有一篇不错的关于 <a href="https://www.ostechnix.com/oh-fish-make-shell-beautiful/" target="_blank" rel="noreferrer">使用oh-my-fish配置的文章</a>，供你参考。</p><p>Fish的其他方面的配置，也是使用oh-my-fish配置会比较方便。关于具体的配置方法，建议你参照 <a href="https://github.com/oh-my-fish/oh-my-fish" target="_blank" rel="noreferrer">官方文档</a>。</p><p>关于环境的最后一个配置，是远程SSH的处理。</p><h2 id="第四步-远程ssh的处理" tabindex="-1">第四步，远程SSH的处理 <a class="header-anchor" href="#第四步-远程ssh的处理" aria-label="Permalink to &quot;第四步，远程SSH的处理&quot;">​</a></h2><p>SSH到其他机器，是开发人员的常见操作，最大的痛点是，怎样保持多次连接的持久性。也就是说，连接断开以后，远端的SSH进程被杀死，之前的工作记录、状态丢失，导致下一次连接进去需要重新设置，交易花销太大。有两类工具可以很好地解决这个问题。</p><p><strong>第一类工具是Tmux或者Screen</strong>，这两个工具比较常见，用来管理一组窗口。</p><p>接下来，我以Tmux为例，与你描述其工作流程：首先SSH到远程服务器，然后用远程机器上的Tmux Client连接到已经运行的Tmux Session上。SSH断开之后，Tmux Client被杀死，但Tmux Session仍然保持运行，意味着命令的运行状态继续存在，下次SSH过去再使用Tmux Client连接即可。</p><p>如果你想深入了解Tmux的概念和搭建过程，可以参考 <a href="http://cenalulu.github.io/linux/tmux/" target="_blank" rel="noreferrer">这篇文章</a>。</p><p><strong>第二类是一个保持连接不中断的工具，移动Shell</strong>（Mobile Shell）。这也是我目前唯一见到的一个。这个工具是MIT做出来的，知道的人不多，是针对移动设备的网络经常断开设计的。</p><p>它的具体原理是，每次初始登录使用SSH，之后就不再使用SSH了，而是使用一个基于UDP的SSP协议，能够在网络断开重连的时候自动重新连接，所以从使用者的角度来看就像从来没有断开过一样。</p><p>接下来， <strong>我以阿里云ECS主机、运行Ubuntu18.04为例，与你分享Mosh+Tumx的具体安装和设置方法。</strong></p><p>第一，服务器端安装并运行Mosh Server。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>junge&amp;#64;iZ4i3zrhuhpdbhZ:~$ sudo apt-get install mosh</span></span></code></pre></div><p>第二，打开服务器上的UDP端口60000~61000。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>junge&amp;#64;iZ4i3zrhuhpdbhZ:~$ sudo ufw allow 60000:61000/udp</span></span></code></pre></div><p>第三，在阿里云的Web界面上修改主机的安全组设置，允许UDP端口60000~61000。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/107e8927ab12b30699699db5ba54af52.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/107e8927ab12b30699699db5ba54af52.jpg" alt=""></a></p><p>第四，在客户端（比如Mac上），安装Mosh Client。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jasonge&amp;#64;Juns-MacBook-Pro-2&amp;#64;l$ brew install mosh</span></span></code></pre></div><p>第五，客户端使用Mosh，用与SSH一样的命令行连接到服务器。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jasonge&amp;#64;Juns-MacBook-Pro-2&amp;#64;l$ mosh junge&amp;#64;&amp;lt;server-ip-or-name&amp;gt;</span></span></code></pre></div><p>下面这个录屏演示的是，我日常工作中使用Mosh + Tmux的流程。期间我会断开无线网，你可以看到Mosh自动连接上了，就好像来没有断过一样。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/9beb7e70191ccd475d530aa4a5654a69.gif" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A0%94%E5%8F%91%E6%95%88%E7%8E%87%E7%A0%B4%E5%B1%80%E4%B9%8B%E9%81%93/images/155538/9beb7e70191ccd475d530aa4a5654a69.gif" alt=""></a></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>今天，我与你分享的是使用命令行工具工作时，涉及的环境配置问题。</p><p>首先，我与你介绍了选择模拟终端、选择和配置Shell的重要准则，并结合案例给出了具体的工具和配置方法，其中涉及的工具包括iTerm2、Bash、Zsh、Fish等。然后，我结合远程SSH这一常见工作场景，给出了使用Tmux和Mosh的优化建议。</p><p>掌握了关于环境配置的这些内容以后，在下一篇文章中，我将与你介绍具体命令行工具的选择和使用。</p><p>其实，我推荐开发者多使用命令行工具，并不是因为它们看起来炫酷，而是它们确实可以帮助我们节省时间、提高个人的研发效能。而高效使用命令行工具的前提，是配置好环境。</p><p>以Mosh为例，我最近经常会使用iPad SSH到远端服务器做一些开发工作。在这种移动开发的场景下，iPad的网络经常断开，每次重新连接开销太大，基本上没办法工作。于是，我最终发现了Mosh，并针对开发场景进行了设置。现在，每次我重新打开iPad的终端时，远程连接自动恢复，好像网络从没有断开过一样。这样一来，我就可以在移动端高效地开发了。</p><p>而对研发团队来说，如果能够对命令行工作环境进行优化和统一，毫无疑问会节省个人选择和配置工具的时间，进而提升团队的研发效能。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>你觉得Tmux和Screen的最大区别是什么？是否有什么场景，我们必须使用其中的一个吗？</p><p>感谢你的收听，欢迎你在评论区给我留言分享你的观点，也欢迎你把这篇文章分享给更多的朋友一起阅读。我们下期再见！</p>`,103)])])}const m=a(t,[["render",i]]);export{u as __pageData,m as default};
